<div class="page-heading"><div><span class="eyebrow">Saison aller-retour</span><h1>Calendrier & résultats</h1><p><?= e($league['name']) ?> · 30 journées</p></div></div>
<section class="panel"><div class="table-toolbar"><form method="get" class="filter-form"><label>Division<select name="league" onchange="this.form.submit()"><?php foreach($leagues as $row): ?><option value="<?= (int)$row['id'] ?>" <?= (int)$row['id']===(int)$league['id']?'selected':'' ?>><?= e($row['short_name']) ?></option><?php endforeach; ?></select></label><label>Journée<select name="matchday" onchange="this.form.submit()"><option value="0">Toutes</option><?php for($i=1;$i<=30;$i++): ?><option value="<?= $i ?>" <?= $selectedMatchday===$i?'selected':'' ?>>J<?= $i ?></option><?php endfor; ?></select></label><noscript><button class="btn btn--sm">Filtrer</button></noscript></form></div><div class="table-wrap"><table class="table"><thead><tr><th>J.</th><th>Date</th><th>Domicile</th><th>Score</th><th>Extérieur</th><th>Statut</th><th></th></tr></thead><tbody><?php foreach($fixtures as $fixture): $own=in_array($context->clubId(),[(int)$fixture['home_club_id'],(int)$fixture['away_club_id']],true); ?><tr class="<?= $own?'is-own':'' ?>"><td>J<?= (int)$fixture['matchday'] ?></td><td><?= format_date($fixture['scheduled_at'],'d/m/Y H:i') ?></td><td><?= e($fixture['home_name']) ?></td><td><strong><?= $fixture['status']==='scheduled'?'—':(int)$fixture['home_score'].' - '.(int)$fixture['away_score'] ?></strong></td><td><?= e($fixture['away_name']) ?></td><td><span class="badge <?= $fixture['status']==='finished'?'badge--success':($fixture['status']==='live'?'badge--danger':'') ?>"><?= e($fixture['status']) ?></span></td><td><?php if($own): ?><a class="text-link" href="/saves/<?= (int)$context->saveId() ?>/matches/<?= (int)$fixture['id'] ?>"><?= $fixture['status']==='finished'?'Rapport':'Match' ?></a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
